function bindNodes(){$$('[data-node]').forEach(b=>{b.onclick=e=>select(b.dataset.node,e.shiftKey);b.ondblclick=()=>enterFunction(b.dataset.node);b.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();select(b.dataset.node);enterFunction(b.dataset.node);}};});}
