function enterFunction(name){const row=rowData().find(r=>r.name===name);if(!Array.isArray(row?.expr)||!program.defs.has(row.expr[0]))return;returnScope={scope,name};scope=row.expr[0];selection=new Set();render();status(`Editing shared definition ${scope}; ${countCalls(scope)} calls are affected.`);}
