const layouts={three:'(let* [preview (ui/viewport (ref scene)) network (ui/graph) inspector (ui/inspector) tools (ui/split "horizontal" network inspector) panels (ui/split "vertical" preview tools) workspace (ui/workspace panels)] workspace)',single:'(let* [preview (ui/viewport (ref scene)) workspace (ui/workspace preview)] workspace)',floating:'(let* [preview (ui/viewport (ref scene)) tools (ui/floating (ui/inspector)) panels (ui/split "horizontal" preview tools) workspace (ui/workspace panels)] workspace)'};
