function layoutDialog(){const editor=[...program.cache.values()].find(v=>v.type==='editor');dialog('Compose the editor',`<p>The applied editor graph describes this preview. Host navigation and recovery stay outside the authored layout.</p><div class="shell-preview">${editor?shellHTML(editor.data.panel):'No editor composition'}</div><div class="inspector-actions"><button data-layout="three">Three panels</button><button data-layout="single">Single view</button><button data-layout="floating">Floating tools</button></div><p class="hint">These choices really change the Lisp and graph. The panel preview is schematic: floating tools are not operating-system windows in this HTML study.</p>`);$$('[data-layout]').forEach(b=>b.onclick=()=>{if(applyLayout(b.dataset.layout))layoutDialog();});}
function actions(){dialog('Actions & keyboard',`<label for="action-search">Find an action</label><input id="action-search" placeholder="Group, function, layout…"><div id="actions"></div><p class="hint">Shortcuts work outside text fields. Tab follows normal keyboard focus. Shift-click selects several bindings. Graph connections are edited by naming a binding in the inspector or Lisp.</p>`);const entries=[['Group / ungroup selection · G',group],['Make function · F',extractDialog],['Graph view · 1',()=>setView('graph')],['List view · 2',()=>setView('list')],['Lisp view · 3',()=>setView('text')],['Compose editor panels',layoutDialog],['Undo · ⌘/Ctrl Z',()=>undo()],['Return to call · Esc',returnToCall]];function show(){const q=$('#action-search').value.toLowerCase();$('#actions').innerHTML='';entries.filter(([s])=>s.toLowerCase().includes(q)).forEach(([label,fn])=>{const b=document.createElement('button');b.className='action';b.textContent=label;b.onclick=()=>{$('#dialog').close();fn();};$('#actions').append(b);});}$('#action-search').oninput=show;show();$('#action-search').focus();}
$$('[data-view]').forEach((b,i)=>{b.onclick=()=>setView(b.dataset.view);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowLeft'?2:1))%3;const target=$$('[data-view]')[next];setView(target.dataset.view);target.focus();};});$('#group').onclick=group;$('#extract').onclick=extractDialog;$('#return').onclick=returnToCall;$('#undo').onclick=()=>undo();$('#redo').onclick=()=>undo(true);$('#help').onclick=actions;$('#close-dialog').onclick=()=>$('#dialog').close();$('#recover').onclick=()=>applyLayout('three');
$('#source').oninput=e=>{draft=e.target.value;dirty=draft!==M.print(ast);$('#preview-label').textContent=dirty?'Last applied version':'Illustrative 2D output';status(dirty?'Unapplied draft · live preview uses the last valid document.':'Source matches the applied document.');};
function applySource(){try{const next=M.read(draft);M.compile(next);dirty=false;if(commit(next,'Source checked and applied in one transaction.'))setView('text');}catch(e){dirty=true;status('Draft error · '+e.message,true);}}
$('#apply').onclick=applySource;$('#discard').onclick=()=>{dirty=false;draft=M.print(ast);$('#preview-label').textContent='Illustrative 2D output';setView('text');status('Discarded draft. The applied document is unchanged.');};
$('#reset').onclick=()=>{dialog('Reset the study?',`<p>Replace the applied document with the original Bloom studio. This is undoable. An unapplied source draft must be applied or discarded first.</p><button id="confirm-reset" class="primary">Reset study</button>`);$('#confirm-reset').onclick=()=>{if(commit(M.read(M.initial),'Reset to the original study.',{})){scope='geometry';selection=new Set(['flower']);$('#dialog').close();render();}};};
$('#export').onclick=()=>{const blob=new Blob([M.print(ast)+'\n'],{type:'text/plain'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='bloom-studio.flow.lisp';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('Exported the applied Lisp. Visual groups are session metadata.');};
$$('[data-journey]').forEach(b=>b.onclick=()=>{const j=b.dataset.journey;if(j==='shape'){go('geometry');selection=new Set(['size']);setView('graph');render();}if(j==='reuse'){returnScope={scope:'geometry',name:'flower'};go('bloom');setView('graph');}if(j==='layout'){go('editor');setView('graph');layoutDialog();}if(j==='code'){setView('text');$('#source').focus();}$('.studio').scrollIntoView({behavior:'smooth',block:'start'});});
document.addEventListener('keydown',e=>{const text=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName);if((e.metaKey||e.ctrlKey)&&e.key==='Enter'&&view==='text'){e.preventDefault();applySource();return;}if(text||$('#dialog').open)return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);return;}if(e.metaKey||e.ctrlKey||e.altKey)return;const key=e.key.toLowerCase();if(key==='g')group();if(key==='f')extractDialog();if(key==='escape')returnToCall();if(key==='?')actions();if(['1','2','3'].includes(key))setView(['graph','list','text'][Number(key)-1]);});
window.addEventListener('beforeunload',e=>{if(dirty||past.length){e.preventDefault();e.returnValue='';}});
render();
